// Helper to validate chord lines
const chromaticScaleSharp = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
const chromaticScaleFlat  = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"];

const SINGLE_CHORD_REGEX = /^[A-G][b#]?(?:maj|min|m|sus|dim|aug|add|M)?[0-9]*(?:sus[0-9]*)?(?:add[0-9]*)?(?:\/[A-G][b#]?)?$/;

function isStrictChordToken(t) {
  const clean = t.replace(/[\(\)\[\],\-]/g, '').trim();
  if (!clean) return true;
  if (clean === '2x' || clean === '3x' || clean === '4x' || clean === 'x2' || clean === 'x4') return true;
  return SINGLE_CHORD_REGEX.test(clean);
}

function isChordLine(line) {
  const trimmed = line.trim();
  if (!trimmed || (trimmed.startsWith('[') && trimmed.endsWith(']'))) return false;
  const tokens = trimmed.split(/\s+/).filter(t => t.length > 0);
  if (tokens.length === 0) return false;
  let chordCount = 0;
  for (const t of tokens) {
    if (isStrictChordToken(t)) chordCount++;
  }
  return (chordCount / tokens.length) >= 0.75 && chordCount >= 1;
}

